[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ChartPulse — Track All Markets</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg-primary: #0F0F0F;
      --bg-secondary: #1a1a2e;
      --bg-card: #16213e;
      --bg-hover: #1f2b47;
      --accent-blue: #2962FF;
      --accent-blue-hover: #1e53e5;
      --text-primary: #FFFFFF;
      --text-secondary: #A0AEC0;
      --text-muted: #718096;
      --green: #00C853;
      --red: #F7525F;
      --border: #2D3748;
      --border-light: #4A5568;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg-primary);
      color: var(--text-primary);
      line-height: 1.5;
      min-height: 100vh;
    }

    a { color: inherit; text-decoration: none; }

    /* Header */
    .header {
      background: var(--bg-secondary);
      border-bottom: 1px solid var(--border);
      padding: 0 24px;
      position: sticky;
      top: 0;
      z-index: 100;
    }

    .header-inner {
      max-width: 1600px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-weight: 700;
      font-size: 20px;
      color: var(--text-primary);
    }

    .logo svg { width: 32px; height: 32px; }

    .nav {
      display: flex;
      gap: 32px;
    }

    .nav a {
      color: var(--text-secondary);
      font-size: 14px;
      font-weight: 500;
      transition: color 0.15s;
      cursor: pointer;
    }

    .nav a:hover { color: var(--text-primary); }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .btn {
      padding: 8px 16px;
      border-radius: 6px;
      font-size: 14px;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.15s;
      border: none;
      display: inline-flex;
      align-items: center;
      gap: 6px;
    }

    .btn-ghost {
      background: transparent;
      color: var(--text-secondary);
    }

    .btn-ghost:hover { color: var(--text-primary); }

    .btn-primary {
      background: var(--accent-blue);
      color: white;
    }

    .btn-primary:hover { background: var(--accent-blue-hover); }

    /* Hero */
    .hero {
      background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
      padding: 80px 24px;
      text-align: center;
      border-bottom: 1px solid var(--border);
    }

    .hero h1 {
      font-size: 48px;
      font-weight: 700;
      margin-bottom: 16px;
      max-width: 800px;
      margin-left: auto;
      margin-right: auto;
      letter-spacing: -0.02em;
    }

    .hero p {
      font-size: 18px;
      color: var(--text-secondary);
      max-width: 600px;
      margin: 0 auto 32px;
    }

    .hero-cta {
      display: flex;
      gap: 12px;
      justify-content: center;
    }

    .hero-cta .btn { padding: 12px 24px; font-size: 16px; }

    /* Market Summary Tabs */
    .market-summary {
      background: var(--bg-secondary);
      border-bottom: 1px solid var(--border);
      padding: 16px 24px;
    }

    .market-summary-inner {
      max-width: 1600px;
      margin: 0 auto;
    }

    .tabs {
      display: flex;
      gap: 4px;
      margin-bottom: 16px;
      overflow-x: auto;
    }

    .tab {
      padding: 8px 16px;
      background: transparent;
      border: none;
      color: var(--text-secondary);
      font-size: 13px;
      font-weight: 500;
      cursor: pointer;
      border-radius: 6px;
      transition: all 0.15s;
      white-space: nowrap;
    }

    .tab:hover { background: var(--bg-hover); color: var(--text-primary); }
    .tab.active { background: var(--accent-blue); color: white; }

    .market-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 12px;
    }

    .market-card {
      background: var(--bg-card);
      border-radius: 8px;
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .market-card .ticker {
      font-size: 12px;
      color: var(--text-muted);
      font-weight: 500;
    }

    .market-card .price {
      font-size: 20px;
      font-weight: 600;
      font-family: 'Inter', monospace;
    }

    .market-card .change {
      font-size: 13px;
      font-weight: 500;
    }

    .change.positive { color: var(--green); }
    .change.negative { color: var(--red); }

    /* Section */
    .section {
      max-width: 1600px;
      margin: 0 auto;
      padding: 48px 24px;
      border-bottom: 1px solid var(--border);
    }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 24px;
    }

    .section-title {
      font-size: 20px;
      font-weight: 600;
    }

    /* Community Ideas */
    .ideas-tabs {
      display: flex;
      gap: 8px;
      margin-bottom: 24px;
    }

    .ideas-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
      gap: 16px;
    }

    .idea-card {
      background: var(--bg-card);
      border-radius: 12px;
      padding: 20px;
      border: 1px solid var(--border);
      transition: border-color 0.15s;
    }

    .idea-card:hover { border-color: var(--border-light); }

    .idea-card-header {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 12px;
    }

    .idea-avatar {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: var(--bg-hover);
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 600;
      font-size: 14px;
      color: var(--accent-blue);
    }

    .idea-author { font-weight: 600; font-size: 14px; }
    .idea-time { font-size: 12px; color: var(--text-muted); }

    .idea-title {
      font-size: 15px;
      font-weight: 600;
      margin-bottom: 8px;
      color: var(--text-primary);
    }

    .idea-preview {
      font-size: 13px;
      color: var(--text-secondary);
      margin-bottom: 12px;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .idea-stats {
      display: flex;
      gap: 16px;
      font-size: 12px;
      color: var(--text-muted);
    }

    .idea-stat { display: flex; align-items: center; gap: 4px; }

    .idea-tag {
      display: inline-block;
      padding: 4px 8px;
      background: var(--bg-hover);
      border-radius: 4px;
      font-size: 11px;
      font-weight: 500;
      color: var(--text-secondary);
      margin-right: 8px;
    }

    .idea-tag.bullish { background: rgba(0, 200, 83, 0.15); color: var(--green); }
    .idea-tag.bearish { background: rgba(247, 82, 95, 0.15); color: var(--red); }

    /* Trending Stocks */
    .trending-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 12px;
    }

    .trending-card {
      background: var(--bg-card);
      border-radius: 8px;
      padding: 16px;
      border: 1px solid var(--border);
    }

    .trending-card .ticker {
      font-weight: 700;
      font-size: 16px;
      margin-bottom: 4px;
    }

    .trending-card .company {
      font-size: 12px;
      color: var(--text-muted);
      margin-bottom: 8px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .trending-card .price {
      font-size: 18px;
      font-weight: 600;
      font-family: 'Inter', monospace;
      margin-bottom: 4px;
    }

    /* Footer */
    .footer {
      background: var(--bg-secondary);
      border-top: 1px solid var(--border);
      padding: 48px 24px;
    }

    .footer-inner {
      max-width: 1600px;
      margin: 0 auto;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(4, 1fr);
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand p {
      color: var(--text-secondary);
      font-size: 14px;
      margin-top: 12px;
      max-width: 280px;
    }

    .footer-col h4 {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--text-muted);
      margin-bottom: 16px;
    }

    .footer-col ul { list-style: none; }

    .footer-col li { margin-bottom: 10px; }

    .footer-col a {
      color: var(--text-secondary);
      font-size: 14px;
      transition: color 0.15s;
    }

    .footer-col a:hover { color: var(--text-primary); }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 24px;
      border-top: 1px solid var(--border);
      font-size: 13px;
      color: var(--text-muted);
    }

    .footer-legal {
      display: flex;
      gap: 24px;
    }

    .footer-legal a { color: var(--text-muted); transition: color 0.15s; }
    .footer-legal a:hover { color: var(--text-secondary); }

    /* Responsive */
    @media (max-width: 1024px) {
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .nav { display: none; }
    }

    @media (max-width: 768px) {
      .hero h1 { font-size: 32px; }
      .hero { padding: 48px 24px; }
      .footer-grid { grid-template-columns: 1fr; gap: 32px; }
      .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
    }

    /* Sparkline mini chart */
    .sparkline {
      width: 60px;
      height: 24px;
    }

    .tab-content { display: none; }
    .tab-content.active { display: block; }

    /* Performance badges */
    .perf-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
      margin-top: 16px;
    }

    .perf-item {
      background: var(--bg-card);
      border-radius: 8px;
      padding: 12px;
      text-align: center;
    }

    .perf-label { font-size: 11px; color: var(--text-muted); margin-bottom: 4px; }
    .perf-value { font-size: 14px; font-weight: 600; }
  </style>
</head>
