      padding: 6px 12px;
      background: var(--bg-hover);
      border: none;
      border-radius: 4px;
      color: var(--text-secondary);
      font-size: 12px;
      cursor: pointer;
      transition: all 0.15s;
      display: flex;
      align-items: center;
      gap: 4px;
    }

    .action-btn:hover { color: var(--text-primary); background: var(--border); }
    .action-btn.liked { color: var(--red); }

    /* Pagination */
