      display: flex;
      justify-content: center;
      align-items: center;
      gap: 8px;
      padding: 24px 0;
    }

    .page-btn {
      padding: 8px 14px;
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 6px;
      color: var(--text-secondary);
      font-size: 14px;
      cursor: pointer;
      transition: all 0.15s;
    }

    .page-btn:hover { border-color: var(--border-light); color: var(--text-primary); }
    .page-btn.active { background: var(--accent-blue); border-color: var(--accent-blue); color: white; }
    .page-btn:disabled { opacity: 0.5; cursor: not-allowed; }

    /* Footer */
    .footer {
      background: var(--bg-secondary);
      border-top: 1px solid var(--border);
      padding: 48px 24px;
    }

    .footer-inner {
      max-width: 1400px;
      margin: 0 auto;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(4, 1fr);
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand p {
      color: var(--text-secondary);
      font-size: 14px;
      margin-top: 12px;
      max-width: 280px;
    }

    .footer-col h4 {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--text-muted);
      margin-bottom: 16px;
    }

    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 10px; }
    .footer-col a { color: var(--text-secondary); font-size: 14px; transition: color 0.15s; }
    .footer-col a:hover { color: var(--text-primary); }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 24px;
      border-top: 1px solid var(--border);
      font-size: 13px;
      color: var(--text-muted);
    }

    .footer-legal { display: flex; gap: 24px; }
    .footer-legal a { color: var(--text-muted); transition: color 0.15s; }
    .footer-legal a:hover { color: var(--text-secondary); }

    /* Responsive */
    @media (max-width: 1024px) {
      .ideas-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .nav { display: none; }
    }

    @media (max-width: 768px) {
      .page-header { flex-direction: column; gap: 16px; align-items: flex-start; }
      .filters { flex-direction: column; }
      .footer-grid { grid-template-columns: 1fr; gap: 32px; }
      .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
    }
  </style>
